import{_ as s,c as i,o as t,ag as l}from"./chunks/framework.3IuuWm4t.js";const e="/siyuan-plugin-publisher/images/shots/halo-basic-auth.webp",k=JSON.parse('{"title":"Halo API 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/common-halo.md","filePath":"platforms/common-halo.md","lastUpdated":1795809563000}'),n={name:"platforms/common-halo.md"};function o(h,a,r,d,p,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="halo-api-配置指南" tabindex="-1">Halo API 配置指南 <a class="header-anchor" href="#halo-api-配置指南" aria-label="Permalink to &quot;Halo API 配置指南&quot;">​</a></h1><p>通过 <strong>Halo API</strong>（基础认证）发布到 Halo 2.x 博客，对应平台列表里的 <strong>Halo29</strong>。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可访问的 Halo 2.x 站点。</li><li>能登录该站点的<strong>用户名与密码</strong>。</li><li>Halo <strong>2.20 及以上</strong>需要先开启 Basic Auth，见下一节。</li></ol><h2 id="二、halo-2-20-需要开启-basic-auth" tabindex="-1">二、Halo 2.20+ 需要开启 Basic Auth <a class="header-anchor" href="#二、halo-2-20-需要开启-basic-auth" aria-label="Permalink to &quot;二、Halo 2.20+ 需要开启 Basic Auth&quot;">​</a></h2><p>Halo 2.20 起默认关闭 Basic Auth，而 Halo29 正是用它做认证。开启方式是在 <strong>Halo 容器的启动命令</strong>里追加一个参数：</p><p><img src="'+e+`" alt="在 Halo 容器启动命令里追加参数" loading="lazy"></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--halo.security.basic-auth.disabled</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>以 Docker Compose 为例，把参数加到 <code>command</code> 里：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  halo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">registry.fit2cloud.com/halo/halo:2.20</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">--halo.security.basic-auth.disabled=false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>以 <code>docker run</code> 为例：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> halo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8090:8090</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  registry.fit2cloud.com/halo/halo:2.20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --halo.security.basic-auth.disabled=false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>改完<strong>重启容器</strong>生效。之后按下面的步骤配置即可正常使用。</p><div class="tip custom-block"><p class="custom-block-title">在 Portainer 里改</p><p>容器 → <strong>Duplicate/Edit</strong> → 找到 <strong>Command</strong> 那一行，在现有参数末尾追加 <code>--halo.security.basic-auth.disabled=false</code>，然后重新创建容器。</p></div><div class="warning custom-block"><p class="custom-block-title">关于安全性</p><p>Basic Auth 会让账号密码以可解码的方式随请求发送。建议只在自用或内网站点开启，并确保站点使用 HTTPS。Halo 官方的 Basic Auth 说明见 <a href="https://docs.halo.run/developer-guide/restful-api/introduction/#basic-auth" target="_blank" rel="noreferrer">RESTful API 文档</a>。</p></div><h2 id="三、配置" tabindex="-1">三、配置 <a class="header-anchor" href="#三、配置" aria-label="Permalink to &quot;三、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>Halo 站点首页地址，通常与 API 地址一致，如 <code>https://yourhalo.com</code></td></tr><tr><td>API 地址</td><td>Halo 站点 API 地址，通常与首页地址相同</td></tr><tr><td>用户名</td><td>Halo 登录用户名（非令牌）</td></tr><tr><td>密码</td><td>Halo 登录密码，与用户名一起用于 API 认证（非令牌）</td></tr><tr><td>预览规则</td><td>默认 <code>/archives/{slug}</code>；查看链接为 <code>https://&lt;host&gt;/archives/&lt;slug&gt;</code>，可修改</td></tr><tr><td>图床</td><td>三选一：「不使用」按原地址引用图片（图片需可公网访问）；「当前平台」上传到 Halo 附件，Halo 2.20+ 会跟随站点「文章附件存储策略」（本地存储或 S3 等对象存储），旧版 Halo 使用本地默认策略；「PicGo」先传外部图床再引用外链。带思源本地图片发布时选「当前平台」</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」，确认 API 认证通过后，选择文章所属分类并保存。2.4.0 起会在此阶段检查受保护接口，认证失败时直接显示处理提示。</li><li>快速发布 → 选 Halo29 → 发布。</li></ol><h2 id="五、题头图与图片复用" tabindex="-1">五、题头图与图片复用 <a class="header-anchor" href="#五、题头图与图片复用" aria-label="Permalink to &quot;五、题头图与图片复用&quot;">​</a></h2><ul><li>封面按「思源题头图链接 → 正文首图链接 → 自定义上传」的顺序解析；前两者直接使用链接，不额外上传图片。</li><li>题头图不会再出现在正文首图；发布表单里的「封面图」可填写链接或上传自定义图片，主动选择会优先于自动解析。</li><li>没有题头图、正文首图或自定义封面时，更新会保留 Halo 端现有封面。</li><li>正文图片按内容复用已上传的 Halo 附件：重复更新不会重复上传；图片内容变化或附件被删除时会重新上传。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="提示「halo-api-鉴权失败」-或旧版出现文章发布失败、find-错误" tabindex="-1">提示「Halo API 鉴权失败」，或旧版出现文章发布失败、find 错误 <a class="header-anchor" href="#提示「halo-api-鉴权失败」-或旧版出现文章发布失败、find-错误" aria-label="Permalink to &quot;提示「Halo API 鉴权失败」，或旧版出现文章发布失败、find 错误&quot;">​</a></h3><p>2.4.0 修复了 Halo API 在认证失败时仍继续处理响应、导致显示 <code>Cannot read properties of undefined (reading &#39;find&#39;)</code> 或笼统的「Halo 文章发布失败」的问题。现在会在配置验证阶段检查认证状态；发布、更新、读取文章或上传图片时遇到认证失败，也会保留可直接操作的错误提示。</p><p>若使用 Halo 2.20 及以上，请先检查 Basic Auth 是否已开启：</p><ol><li>按第二节在现有容器启动命令中追加 <code>--halo.security.basic-auth.disabled=false</code>，保留原有参数与数据挂载配置。</li><li>使新的启动参数生效后，回到插件再次点「验证」。</li><li>如果仍然失败，检查用户名、密码以及账号权限。</li></ol><p>升级插件不会自动开启服务器的 Basic Auth。不希望调整容器配置时，可以保留现有 Halo29 账号配置，另行配置 <a href="./custom-haloweb.html">Halo 网页版</a>，通过登录授权使用。</p><h3 id="验证通过但发布失败" tabindex="-1">验证通过但发布失败 <a class="header-anchor" href="#验证通过但发布失败" aria-label="Permalink to &quot;验证通过但发布失败&quot;">​</a></h3><p>确认平台首页与 API 地址可访问（http 与 https 保持一致）、用户名与密码正确，且账号有发文与上传附件的权限。</p><h3 id="图片要怎么发布" tabindex="-1">图片要怎么发布 <a class="header-anchor" href="#图片要怎么发布" aria-label="Permalink to &quot;图片要怎么发布&quot;">​</a></h3><p>选「当前平台」图床，图片会上传到 Halo 附件。Halo 2.20+ 的图片地址由站点的「文章附件存储策略」决定：本地存储通常为 <code>/upload/&lt;图片名&gt;</code>，配置了 S3/对象存储时则是该存储返回的地址；插件会按站点配置上传，不再固定写本地存储。</p><h3 id="查看链接打不开" tabindex="-1">查看链接打不开 <a class="header-anchor" href="#查看链接打不开" aria-label="Permalink to &quot;查看链接打不开&quot;">​</a></h3><p>确认预览规则（默认 <code>/archives/{slug}</code>）与该文章的 slug 匹配，且文章已发布、不是草稿状态。</p><h3 id="文章别名和站点设置不一致" tabindex="-1">文章别名和站点设置不一致 <a class="header-anchor" href="#文章别名和站点设置不一致" aria-label="Permalink to &quot;文章别名和站点设置不一致&quot;">​</a></h3><p>Halo 2.10+ 新建文章时会读取站点的「别名生成策略」（按标题 / 时间戳 / Short UUID / UUID）生成默认别名；发布页手动修改的别名优先。更新已发布文章沿用原别名，避免链接变化。</p><h3 id="和「halo网页版」有什么区别" tabindex="-1">和「Halo网页版」有什么区别 <a class="header-anchor" href="#和「halo网页版」有什么区别" aria-label="Permalink to &quot;和「Halo网页版」有什么区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Halo29（本页）</th><th>Halo网页版</th></tr></thead><tbody><tr><td>认证</td><td>用户名 + 密码（Basic Auth）</td><td>浏览器 Cookie</td></tr><tr><td>适用版本</td><td>Halo 2.x（2.20+ 需开 Basic Auth）</td><td>Halo 2.x</td></tr><tr><td>需要改容器参数</td><td>2.20+ 需要</td><td>不需要</td></tr></tbody></table><p>如果不想改容器配置，可以用 <a href="./custom-haloweb.html">Halo 网页版</a>。</p>`,38)])])}const b=s(n,[["render",o]]);export{k as __pageData,b as default};
